/* ===== Numeria Quest — Desain Hero Baru: "Ksatria Kerajaan" (3 job, dari lembar karakter) =====
   Dimuat PALING AKHIR (setelah karakter.js, arena.js, dan monster_pixel.js). Tidak mengubah script.js.
   Menggantikan desain hero lama dengan pixel art dari lembar sprite: rambut hitam + jepit bintang emas, jas navy berlist emas,
   selempang merah, jubah navy-merah, dan senjata ASLI di gambar (pedang / busur emas-biru / tongkat berorb).
   CATATAN: gambar hero di file ini sekarang TANPA senjata; senjata digambar oleh hero_senjata.js sesuai equipment (Pl.eq.w).
   Tiap job punya 2 gambar (tinggi tubuh ~124 baris, titik pijak kaki sama, lebar kanvas 163 x 128):
     - diam  : pose depan, senjata dipegang
     - aksi  : pose serang (pedang terhunus, busur ditarik + anak panah, tongkat + orb bintang)
   Cara kerja:
   - Battle: heroB() digambar ulang. Pose diam saat |a| kecil; pose aksi saat ancang-ancang (a<0) dan menebas/menembak/merapal (a>0).
     Posisi & ukuran sama dengan sebelumnya (tinggi 128 x HERO_SK x hs), kaki tepat di garis tanah.
     Titik ujung senjata (untuk efek sihir, panah, tebasan) diambil dari gambar pose aksi: ujung pedang / ujung anak panah / orb tongkat.
   - Dunia: spr("hero") digambar dari pose depan, tinggi sama dengan sprite lama (24 petak); KRK_DUNIA_SKALA dari karakter.js tetap berlaku.
   - Pratinjau di layar "Pilih Job" juga memakai gambar baru.
   Yang berubah dari sebelumnya: senjata sekarang ikut gambar (bukan digambar kode), jadi pedang tidak lagi berapi/berwarna elemen;
   saat ulti / tebasan elemen, bilah diberi cahaya berwarna di atas gambar. Ukuran: ubah HERO_SK di bawah. */
(function () {
  const PNG = {
    sword_front:
      "",
    sword_act:
      "",
    archer_front:
      "",
    archer_act:
      "",
    mage_front:
      "",
    mage_act:
      "",
  };
  const META = {
    AX: 70,
    W: 163,
    H: 128,
    sword_front: { head: [74, 6] },
    sword_act: { tip: [160, 110], head: [73, 6] },
    archer_front: { head: [68, 8] },
    archer_act: { tip: [133, 58], head: [71, 12] },
    mage_front: { head: [69, 5] },
    mage_act: { tip: [139, 32], head: [63, 14] },
  };
  const AX = META.AX, // kolom titik pijak (tengah antara kedua kaki) di kanvas
    CW = META.W,
    CH = META.H;
  const HERO_SK = typeof KRK_SEJ_SKALA !== "undefined" ? KRK_SEJ_SKALA : 0.3; // piksel layar per piksel sprite, per satuan hs (hs=5 -> 1.5x)
  // titik tangan & titik cahaya (kolom,baris di kanvas). Ujung senjata pose aksi diambil dari META[job_act].tip
  const IDLE_PT = { sword: [50, 82], archer: [92, 77], mage: [37, 19] }, // pose diam: cahaya "ulti siap" menempel di senjata
    ACT_HAND = { sword: [101, 75], archer: [104, 56], mage: [94, 43] },
    ACT_TIP = {
      sword: META.sword_act.tip,
      archer: META.archer_act.tip,
      mage: [META.mage_act.tip[0] - 13, META.mage_act.tip[1]],
    };

  const F = {}; // F[job] = { idle, act, tint:{}, ready }
  ["sword", "archer", "mage"].forEach((job) => {
    const o = (F[job] = { tint: {}, ready: false, n: 0 });
    ["front", "act"].forEach((v) => {
      const img = new Image();
      img.onload = () => {
        const c = document.createElement("canvas");
        c.width = CW;
        c.height = CH;
        c.getContext("2d").drawImage(img, 0, 0);
        o[v === "front" ? "idle" : "act"] = c;
        if (++o.n === 2) o.ready = true;
      };
      img.src = "data:image/png;base64," + PNG[job + "_" + v];
    });
  });
  const white = (o, v) => {
    const key = v;
    if (o.tint[key]) return o.tint[key];
    const src = o[v],
      c = document.createElement("canvas");
    c.width = CW;
    c.height = CH;
    const x = c.getContext("2d");
    x.drawImage(src, 0, 0);
    x.globalCompositeOperation = "source-in";
    x.fillStyle = "#fff";
    x.fillRect(0, 0, CW, CH);
    return (o.tint[key] = c);
  };
  const job = () => (typeof krkJob === "function" ? krkJob() : "sword");

  /* ---------- battle ---------- */
  const _heroB = heroB;
  heroB = function (x, y, a, col, hs = 3) {
    const jb = job(),
      o = F[jb];
    if (!o || !o.ready) return _heroB(x, y, a, col, hs);
    const k = hs / 3,
      s = hs * HERO_SK,
      ln = Math.round(a * 4 * k),
      fl = an.sp > 6, // berkedip putih saat terkena serangan
      dy =
        hs === 5
          ? typeof ARENA !== "undefined" && ARENA.heroDY != null
            ? ARENA.heroDY
            : -60
          : 0, // koreksi kaki dari arena.js
      act = Math.abs(a) > 0.15,
      v = act ? "act" : "idle",
      dd = globalThis.SWDASH,
      dsh =
        hs === 5 && jb === "sword" && dd && Date.now() - dd.ts < 250 ? dd.x : 0, // dash maju skill petir (diatur skill_fx.js)
      X = x + ln + dsh + Math.round(20 * hs - AX * s),
      Y = y + dy + Math.round(36 * hs - CH * s),
      W2 = Math.round(CW * s),
      H2 = Math.round(CH * s),
      sm = ctx.imageSmoothingEnabled;
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(fl ? white(o, v) : o[v], X, Y, W2, H2);
    if (typeof HEROWPN !== "undefined")
      HEROWPN.draw(ctx, jb, v, X, Y, s, fl, true); // senjata sesuai equipment
    ctx.imageSmoothingEnabled = sm;
    if (typeof HAT !== "undefined" && HAT && typeof hatDraw === "function") {
      const hd = META[jb + (act ? "_act" : "_front")].head;
      hatDraw(
        X + Math.round(hd[0] * s - 8 * hs),
        Y + Math.round(hd[1] * s) + 3,
        hs,
        0,
      ); // topi di kepala
    }
    const P = (p) => [Math.round(X + p[0] * s), Math.round(Y + p[1] * s)],
      tip = P(act ? ACT_TIP[jb] : IDLE_PT[jb]),
      hand = P(act ? ACT_HAND[jb] : IDLE_PT[jb]);
    // cahaya aura (ulti siap / skill elemen) di senjata
    if (col) {
      const z = (14 + Math.max(0, -a) * 8) * k;
      ctx.save();
      ctx.fillStyle = col;
      ctx.globalAlpha = 0.22 + 0.2 * Math.sin(Date.now() / 130);
      ctx.beginPath();
      ctx.arc(tip[0], tip[1], z, 0, 6.283);
      ctx.fill();
      ctx.restore();
    }
    // pedang: cahaya berwarna di sepanjang bilah saat ulti (pelangi) atau tebasan elemen
    const rb = globalThis.RB,
      bc = globalThis.bladeC;
    if (jb === "sword" && act && (rb || bc) && !fl) {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.globalAlpha = 0.55;
      ctx.lineCap = "round";
      ctx.strokeStyle = rb ? `hsl(${(Date.now() / 3) % 360},100%,60%)` : bc;
      ctx.lineWidth = Math.max(3, 5 * k);
      ctx.beginPath();
      ctx.moveTo(hand[0], hand[1]);
      ctx.lineTo(tip[0], tip[1]);
      ctx.stroke();
      ctx.restore();
    }
    return [tip[0], tip[1], hand[0], hand[1]]; // ujung senjata + tangan
  };

  /* ---------- dunia (gaya chibi) ----------
     Seluruh gambar hero (163x128) digambar dengan skala badan (CHIBI.body, senjata ikut mengecil dan tetap menyatu),
     lalu kepala (baris 0..NECK, hanya kolom di sekitar kepala) ditimpa dengan skala lebih besar (CHIBI.head) di titik leher.
     Skala keduanya dinormalkan agar tinggi total tetap sama seperti sebelumnya (24 petak).
     Atur CHIBI: head 1.0 + body 1.0 = proporsi asli; makin besar head / makin kecil body = makin chibi.
     Ukuran & posisi dibulatkan ke piksel kanvas (skala SC) dan diperkecil dengan penghalusan kualitas tinggi. */
  const CHIBI = { head: 1.5, body: 0.78 },
    NECK = 30, // baris tersempit di leher (sama untuk ketiga job)
    OVL = 2, // kepala menimpa badan 2 baris supaya tidak ada celah
    HW = 16; // setengah lebar potongan kepala (kolom): cukup untuk rambut, tidak ikut menyeret orb tongkat / anak panah
  const _spr = spr;
  spr = function (k, x, y, s, al = 1, tint, fr = 0, fl = 0, mm) {
    const jb = job(),
      o = F[jb];
    if (k !== "hero" || mm || !o || !o.ready)
      return _spr(k, x, y, s, al, tint, fr, fl, mm);
    const sc = typeof SC === "number" && SC > 0 ? SC : 1, // piksel kanvas per piksel logis
      q = (v) => Math.round(v * sc) / sc, // bulatkan ke grid piksel kanvas
      f0 =
        ((typeof NPC_WORLD_H === "number"
          ? NPC_WORLD_H
          : 24 *
            (typeof KRK_DUNIA_SKALA !== "undefined" ? KRK_DUNIA_SKALA : 1)) *
          s) /
        CH, // 128 baris = NPC_WORLD_H piksel peta (sama dengan NPC, lihat npc_sheet.js)
      norm = CH / (NECK * CHIBI.head + (CH - NECK) * CHIBI.body), // jaga tinggi total
      fh = f0 * CHIBI.head * norm,
      fb = f0 * CHIBI.body * norm,
      bob = fr ? -Math.round(s * 0.6) : 0, // langkah: tubuh naik sedikit
      cx = q(x + 8 * s),
      foot = y - 8 * s + 24 * s + bob, // garis pijak kaki
      HX = META[jb + "_front"].head[0], // kolom tengah kepala
      src = tint ? white(o, "idle") : o.idle,
      sm = ctx.imageSmoothingEnabled,
      sq = ctx.imageSmoothingQuality,
      // gambar potongan src(sx,sy,sw,sh) -> tujuan (dx,dy,dw,dh), tepi dibulatkan ke piksel kanvas
      part = (sx, sw, sy, sh, dx, dy, f) => {
        const X0 = q(dx),
          X1 = q(dx + sw * f),
          Y0 = q(dy),
          Y1 = q(dy + sh * f);
        ctx.drawImage(src, sx, sy, sw, sh, X0, Y0, X1 - X0, Y1 - Y0);
      };
    ctx.imageSmoothingEnabled = sc > 1.01; // kanvas beresolusi tinggi: perkecil dengan halus; kanvas 1:1: tetap piksel tajam
    ctx.imageSmoothingQuality = "high";
    ctx.globalAlpha = al;
    ctx.save();
    if (fl) {
      ctx.translate(cx, 0); // balik kiri-kanan di sekitar titik pijak
      ctx.scale(-1, 1);
      ctx.translate(-cx, 0);
    }
    // seluruh gambar pada skala badan; titik pijak AX di tengah, kaki di garis pijak
    const bodyTop = foot - CH * fb,
      bx = cx - AX * fb;
    part(0, CW, 0, CH, bx, bodyTop, fb);
    // kepala besar: berputar di titik leher (HX, NECK) pada badan yang sudah dikecilkan
    const nx = bx + HX * fb,
      ny = bodyTop + NECK * fb;
    part(HX - HW, HW * 2, 0, NECK + OVL, nx - HW * fh, ny - NECK * fh, fh);
    // bagian kiri kepala (orb tongkat, bulu anak panah) digambar ulang di depan rambut supaya tidak tertutup
    part(0, HX - HW, 0, NECK + 6, bx, bodyTop, fb);
    if (typeof HEROWPN !== "undefined")
      HEROWPN.draw(ctx, jb, "idle", bx, bodyTop, fb, !!tint, sc > 1.01); // senjata sesuai equipment
    ctx.restore();
    ctx.globalAlpha = 1;
    ctx.imageSmoothingEnabled = sm;
    ctx.imageSmoothingQuality = sq;
  };

  /* ---------- pratinjau layar "Pilih Job" ---------- */
  jobPreviews = function () {
    document.querySelectorAll("canvas[data-jp]").forEach((cv2) => {
      const jb = cv2.dataset.jp,
        o = F[jb],
        c2 = cv2.getContext("2d");
      c2.imageSmoothingEnabled = false;
      c2.clearRect(0, 0, cv2.width, cv2.height);
      if (!o || !o.ready) return;
      const sc = Math.min((cv2.width - 4) / CW, (cv2.height - 4) / CH);
      c2.drawImage(
        o.idle,
        (cv2.width - CW * sc) / 2,
        (cv2.height - CH * sc) / 2,
        CW * sc,
        CH * sc,
      );
      if (typeof HEROWPN !== "undefined")
        HEROWPN.draw(
          c2,
          jb,
          "idle",
          (cv2.width - CW * sc) / 2,
          (cv2.height - CH * sc) / 2,
          sc,
          false,
          sc < 1,
        );
    });
  };
  // gambar sudah dimuat? segarkan pratinjau begitu semua job siap
  const iv = setInterval(() => {
    if (Object.values(F).every((o) => o.ready)) {
      clearInterval(iv);
      jobPreviews();
    }
  }, 120);
})();
